  const [filtreKategori, setFiltreKategori] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  const [seciliMekan, setSeciliMekan] = useState(null);
  const [aiCevap, setAiCevap] = useState("");
  const [loading, setLoading] = useState(false);

  // 1. Veriyi Çek
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(data))
      .catch(err => console.error("API Hatası:", err));
  }, []);

  // 2. HESAPLAMALAR
  const toplamSure = favoriler.reduce((toplam, m) => toplam + (parseInt(m.sure) || 0), 0);
  const toplamButce = favoriler.reduce((toplam, m) => toplam + (parseInt(m.ucret) || 0), 0);

  const saat = Math.floor(toplamSure / 60);
  const dakika = toplamSure % 60;

  // 3. FONKSİYONLAR
  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => f.id === mekan.id);
    if (varMi) {
      setFavoriler(favoriler.filter(f => f.id !== mekan.id));
    } else {
      setFavoriler([...favoriler, mekan]);
    }
  };

  const rotayiTemizle = () => {
    if (window.confirm("Rotayı tamamen sıfırlamak istiyor musun?")) {
      setFavoriler([]); 
    }
  };

  // 🗺️ ROTAYI HARİTADA GÖSTER
  const rotayiHaritadaGoster = () => {
    if (favoriler.length === 0) return alert("Harita için önce listene mekan eklemelisin!");

    const duraklar = favoriler.map(m => encodeURIComponent(m.ad)).join("/");
    // Google Maps Linki
    const haritaUrl = `https://www.google.com/maps/dir/Antalya+Merkez/${duraklar}`;

    window.open(haritaUrl, '_blank');
  };

  const askAI = async (mekan) => {
    if(!API_KEY || API_KEY.includes("BURAYA")) { alert("Lütfen API Key yapıştırın!"); return; }
    setLoading(true); setAiCevap("");
    try {
      const genAI = new GoogleGenerativeAI(API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-pro"});
      const prompt = `Antalya'daki "${mekan.ad}" hakkında turistler için 2 kısa, ilgi çekici cümle kur.`;
      const result = await model.generateContent(prompt);
      const response = await result.response;
      setAiCevap(response.text());
    } catch (error) { setAiCevap("Hata oluştu."); } 
    finally { setLoading(false); }
  };

  const filtrelenmisMekanlar = mekanlar.filter(m => {
    const katUygun = filtreKategori === 'Hepsi' || m.kategori === filtreKategori;
    const sureUygun = !maxSure || m.sure <= parseInt(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="app-container">
      <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap" rel="stylesheet" />

      <style>{`
        :root { 
          --primary: #0e7490; --primary-dark: #155e75; --accent: #f97316; 
          --bg: #f0f9ff; --card-bg: #ffffff; --text: #334155; --title: #0f172a; 
        }

        body { margin: 0; font-family: 'Poppins', sans-serif; background: var(--bg); color: var(--text); min-height: 100vh; display: flex; flex-direction: column; }
        .app-container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 20px; flex: 1; }

        /* Navbar */
        .navbar { display: flex; justify-content: space-between; align-items: center; padding: 25px 0; margin-bottom: 20px; }
        .brand { font-size: 26px; font-weight: 800; color: var(--primary); letter-spacing: -0.5px; display: flex; align-items: center; gap: 8px; }
        .brand span { color: var(--accent); }
        .brand-icon { font-size: 28px; }

        .nav-stats { display: flex; gap: 40px; background: white; padding: 10px 25px; border-radius: 50px; box-shadow: 0 4px 15px rgba(14, 116, 144, 0.1); }
        .nav-stat-item { text-align: center; }
        .nav-stat-item small { display: block; font-size: 10px; text-transform: uppercase; color: #64748b; letter-spacing: 1px; font-weight: 700; }
        .nav-stat-item strong { font-size: 18px; color: var(--title); font-weight: 700; }
        .budget-val { color: var(--accent) !important; }

        /* Filters */
        .filters-container {
          background: var(--card-bg); padding: 20px; border-radius: 20px;
          display: flex; gap: 15px; align-items: center; flex-wrap: wrap;
          box-shadow: 0 10px 30px -10px rgba(14, 116, 144, 0.15); border: 1px solid white; margin-bottom: 40px;
        }
        .input-styled { padding: 14px 20px; border: 1px solid #e2e8f0; border-radius: 12px; outline: none; font-family: 'Poppins', sans-serif; color: var(--text); background: #f8fafc; font-size: 14px; font-weight: 500; }

        .btn-tool { padding: 14px 24px; border-radius: 12px; border: none; cursor: pointer; font-weight: 600; font-size: 14px; display: flex; align-items: center; gap: 10px; transition: all 0.3s; box-shadow: 0 4px 6px rgba(0,0,0,0.05); }
        .btn-map { background: var(--primary); color: white; flex-grow: 1; justify-content: center; }
        .btn-map:hover { background: var(--primary-dark); transform: translateY(-2px); box-shadow: 0 10px 20px rgba(14, 116, 144, 0.3); }
        .btn-danger { color: #ef4444; background: white; border: 1px solid #fecaca; }
        .btn-danger:hover { background: #fef2f2; border-color: #ef4444; }

        /* Grid & Cards */
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 30px; }
        .card { background: var(--card-bg); border-radius: 24px; overflow: hidden; border: 1px solid transparent; transition: all 0.3s ease; display: flex; flex-direction: column; box-shadow: 0 4px 20px rgba(0,0,0,0.03); }
        .card:hover { transform: translateY(-8px); box-shadow: 0 20px 40px -10px rgba(14, 116, 144, 0.15); border-color: rgba(14, 116, 144, 0.2); }

        .card-img-wrap { height: 220px; position: relative; overflow: hidden; }
        .card-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.6s ease; }
        .card-img-wrap:hover .card-img { transform: scale(1.1); }

        .badge { position: absolute; top: 15px; right: 15px; background: rgba(255,255,255,0.95); color: var(--primary); padding: 6px 14px; border-radius: 50px; font-weight: 700; font-size: 11px; text-transform: uppercase; box-shadow: 0 4px 10px rgba(0,0,0,0.1); }
        .weather-badge { position: absolute; top: 15px; left: 15px; background: rgba(15, 23, 42, 0.6); color: #fbbf24; padding: 6px 14px; border-radius: 50px; font-weight: 600; font-size: 11px; backdrop-filter: blur(4px); display: flex; align-items: center; gap: 6px; }

        .card-body { padding: 25px; flex-grow: 1; display: flex; flex-direction: column; }
        .card-title { margin: 0 0 8px 0; font-size: 18px; font-weight: 700; color: var(--title); }
        .card-desc { font-size: 13px; color: #64748b; margin-bottom: 20px; line-height: 1.6; flex-grow: 1; }
        .meta-row { display: flex; justify-content: space-between; align-items: center; font-size: 13px; color: #475569; font-weight: 500; padding-top: 15px; border-top: 1px dashed #e2e8f0; }
        .price { color: var(--primary); font-weight: 700; background: #ecfeff; padding: 6px 12px; border-radius: 8px; }

        .card-actions { padding: 15px 25px; background: #f8fafc; display: flex; gap: 12px; }
        .btn { flex: 1; padding: 12px; border: none; border-radius: 12px; cursor: pointer; font-weight: 600; font-size: 13px; transition: 0.2s; }
        .btn-ai { background: white; border: 2px solid #e2e8f0; color: #64748b; }
        .btn-ai:hover { border-color: var(--accent); color: var(--accent); background: white; }
        .btn-add { background: var(--primary); color: white; box-shadow: 0 4px 10px rgba(14, 116, 144, 0.2); }
        .btn-add:hover { background: var(--primary-dark); }
        .btn-remove { background: white; border: 2px solid #ef4444; color: #ef4444; }
        .btn-remove:hover { background: #ef4444; color: white; }

        /* Footer */
        .footer { margin-top: 80px; padding: 40px 0; border-top: 1px solid #e2e8f0; text-align: center; color: #94a3b8; font-size: 13px; }
        .footer strong { color: var(--primary); }
      `}</style>

      {/* Navbar */}
      <nav className="navbar">
        <div className="brand">
          <span className="brand-icon">🧭</span> ROTA<span>ASİSTANI</span>
        </div>
        <div className="nav-stats">
          <div className="nav-stat-item">
            <small>SÜRE</small>
            <strong>{saat} sa {dakika} dk</strong>
          </div>
          <div style={{width:'1px', background:'#e2e8f0'}}></div>
          <div className="nav-stat-item">
            <small>BÜTÇE</small>
            <strong className="budget-val">{toplamButce} ₺</strong>
          </div>
        </div>
      </nav>

      {/* Filters */}
      <div className="filters-container">
        <select className="input-styled" value={filtreKategori} onChange={(e) => setFiltreKategori(e.target.value)}>
          <option value="Hepsi">Tüm Kategoriler</option>
          <option value="Tarih">🏛 Tarih</option>
          <option value="Doğa">🌲 Doğa</option>
          <option value="Eğlence">🎢 Eğlence</option>
          <option value="Yemek">🍽️ Yemek</option>
        </select>
        <input type="number" className="input-styled" placeholder="Maks. Süre (dk)" value={maxSure} onChange={(e) => setMaxSure(e.target.value)} style={{width: '120px'}} />
        <div style={{flex: 1}}></div>
        <button type="button" className="btn-tool btn-map" onClick={rotayiHaritadaGoster}>🗺️ Rotayı Haritada Gör</button>
        <button type="button" className="btn-tool btn-danger" onClick={rotayiTemizle}>🗑️ Sıfırla</button>
      </div>

      {/* Grid */}
      <div className="grid">
        {filtrelenmisMekanlar.map((mekan) => {
          const favorideMi = favoriler.some(f => f.id === mekan.id);
          return (
            <div key={mekan.id} className="card">
              <div className="card-img-wrap">
                <img src={mekan.resim} className="card-img" alt={mekan.ad} onError={(e) => {e.target.src="https://via.placeholder.com/300?text=Gorsel+Yok"}} />
                <span className="badge">{mekan.kategori}</span>
                <span className="weather-badge">{mekan.hava}</span>
              </div>
              <div className="card-body">
                <h3 className="card-title">{mekan.ad}</h3>
                <p className="card-desc">{mekan.aciklama}</p>
                <div className="meta-row">
                  <span>📍 {mekan.bolge} • ⏱ {mekan.sure} dk</span>
                  <span className="price">{mekan.ucret === 0 ? "Ücretsiz" : `${mekan.ucret} ₺`}</span>
                </div>
              </div>
              <div className="card-actions">
                <button type="button" className="btn btn-ai" onClick={() => { setSeciliMekan(mekan); askAI(mekan); }}>✨ AI Bilgi</button>
                <button type="button" className={`btn ${favorideMi ? 'btn-remove' : 'btn-add'}`} onClick={() => toggleFavori(mekan)}>
                  {favorideMi ? 'Listeden Çıkar' : 'Rotaya Ekle +'}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* Footer */}
      <footer className="footer">
        <p>© 2026 <strong>Rota Asistanı</strong>. Tüm hakları saklıdır. | Antalya Dijital Gezi Rehberi</p>
      </footer>

      {/* Modal */}
      {seciliMekan && (
        <div style={{position:'fixed', top:0, left:0, right:0, bottom:0, background:'rgba(14, 116, 144, 0.6)', display:'flex', alignItems:'center', justifyContent:'center', zIndex:1000, backdropFilter: 'blur(5px)'}} onClick={() => setSeciliMekan(null)}>
          <div style={{background:'white', padding:'30px', borderRadius:'24px', maxWidth:'500px', width:'90%', boxShadow:'0 25px 50px -12px rgba(0,0,0,0.25)'}} onClick={e => e.stopPropagation()}>
            <h2 style={{marginTop:0, color:'var(--primary)'}}>{seciliMekan.ad}</h2>
            <p style={{color:'#475569', lineHeight:'1.6'}}>{seciliMekan.aciklama}</p>
            <div style={{background:'#f0f9ff', padding:'20px', borderRadius:'16px', marginTop:'20px', border:'1px solid #bae6fd', color:'#0369a1'}}>
              {loading ? "🤖 Yapay zeka gezi notlarını hazırlıyor..." : aiCevap || "Cevap bekleniyor..."}
            </div>
            <button type="button" style={{marginTop:'25px', width:'100%', padding:'14px', background:'var(--primary)', color:'white', border:'none', borderRadius:'12px', fontWeight:'600', cursor:'pointer', fontSize:'14px'}} onClick={() => setSeciliMekan(null)}>Kapat</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
